local Catalog = { by_montage = {}, by_family = {} }

local function normalized(value)
    return string.lower(tostring(value or "")):gsub("[^%w]", "")
end

local function add_asset(family, category, participant_tag, asset)
    local lower = string.lower(asset)
    local phase = string.find(lower, "_max", 1, true) and "max"
        or (string.find(lower, "_min", 1, true) and "min")
        or "normal"
    Catalog.by_montage[normalized(asset)] = {
        asset = asset, asset_paths = {}, category = category,
        catalog_refs = { "Playtest/UE5.7/TableHAnim-NameMap" },
        evidence = "ue57_exact_table_hanim_namemap", hanime_id = family,
        participant_tag = participant_tag, phase = phase,
    }
end

